static void opticon_write_control_callback ( struct urb * urb ) { struct usb_serial_port * port = urb -> context ; struct opticon_private * priv = usb_get_serial_port_data ( port ) ; int status = urb -> status ; cfs_time_t flags ; kfree ( urb -> transfer_buffer ) ; kfree ( urb -> setup_packet ) ; if ( status ) { dev_dbg ( & port -> dev , "%s - non-zero urb status received: %d\n" , __func__ , status ) ; } spin_lock_irqsave ( & priv -> lock , flags ) ; -- priv -> outstanding_urbs ; spin_unlock_irqrestore ( & priv -> lock , flags ) ; usb_serial_port_softint ( port ) ; } 